import{_ as r}from"./chunks/bb86b2976d876d31587d.BfM7xQ_P.js";import{_ as t}from"./chunks/f02b384d940e32141811.BV87ILES.js";import{_ as o,C as l,o as n,c as i,j as e,a as s,E as h,a6 as c}from"./chunks/framework.CnPv4DE1.js";const y=JSON.parse('{"title":"工作的未来是玩耍（如何开创你自己的事业）","description":"","frontmatter":{"title":"工作的未来是玩耍（如何开创你自己的事业）","originalTitle":"The Future Of Work Is Play (How To Create Your Own Career)","date":"2023-12-16","originalUrl":"https://thedankoe.com/letters/the-future-of-work-is-play-how-to-create-your-own-career/","minutes":17,"sourceHash":"7e4f10877c8f025a02ee250fe46c3897217feb72eb2c56f16a3ae0cc1cbd72ed","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-future-of-work-is-play-how-to-create-your-own-career/"}]]},"headers":[],"relativePath":"letters/the-future-of-work-is-play-how-to-create-your-own-career.md","filePath":"letters/the-future-of-work-is-play-how-to-create-your-own-career.md"}'),u={name:"letters/the-future-of-work-is-play-how-to-create-your-own-career.md"};function d(f,p,m,k,b,w){const a=l("ArticleMeta");return n(),i("div",null,[p[0]||(p[0]=e("h1",{id:"工作的未来是玩耍-如何开创你自己的事业",tabindex:"-1"},[s("工作的未来是玩耍（如何开创你自己的事业） "),e("a",{class:"header-anchor",href:"#工作的未来是玩耍-如何开创你自己的事业","aria-label":'Permalink to "工作的未来是玩耍（如何开创你自己的事业）"'},"​")],-1)),h(a),p[1]||(p[1]=c('<p><a href="https://www.youtube.com/embed/fXhmecN-AFw?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>痴迷是你通向伟大的关键。</p><p>让自己接触更多的体验，而不是分心，让好奇心拉着你掉进探索的兔子洞。</p><p>一旦你找到了让你无法自拔的事物，就努力让它成为你生活中可持续的一部分。</p><p>这是我在童年时领悟到的一个道理。</p><p>我一直痴迷于寻找一种更好的生活方式。</p><p>无论走到哪里，我都会密切关注人们的行为。不是为了评判，而是为了洞察。我想了解哪些行为会带来美好的生活，哪些会带来糟糕的生活。</p><p>我经常发现自己在质疑：是什么，怎么做，以及为什么。</p><p>他们在追求什么？</p><p>如果每一个行动都是为了一个有意识或无意识的目标，那么似乎每个人都渴望变得超重、不健康、过度劳累和破产。他们没有能够塑造自己决策的自发目标。</p><p>那个人是怎么走到今天这一步的？</p><p>他们为什么看起来是那个样子？</p><p>是因为他们早餐拿了一杯1000卡路里的甜点饮料，配上一个包装纸上漏油的三明治吗？</p><p>为什么他们要去干同一份显然给他们带来巨大痛苦的工作？</p><p>他们怎么会看不到周围的机会？那个就在他们眼前展开的数字世界？一个他们可以用极短的时间来学习和构建的信息与科技世界？</p><p>由于我的质疑，我习惯于认为找一份朝九晚五的工作是我人生中可能发生的最坏结果。</p><p>似乎人们一旦接受了工作机会，就注定要过一种贪图安逸的生活。</p><p>他们在拥有真正的财务能力将时间和精力投入到这些事情上之前，就会给自己揽下一堆没完没了的责任——房贷、配偶和孩子。看起来他们很快就成了成年人，却始终无法收获成为成年人的回报。</p><p>他们把自己拴在一份薪水上，因为他们从未做出能带来更多金钱和时间的选择。</p><p>就业的危险远不止于此。</p><p>在我们深入探讨之前，Kortex（<a href="https://kortex.co/" target="_blank" rel="noreferrer">该软件</a>）已接近完工。Kortex（<a href="https://university.kortex.co/" target="_blank" rel="noreferrer">大学</a>）的成员将获得抢先体验资格，以及一份针对未来工作的革命性课程（学校教不了的那种）。</p><h3 id="就业的心理学与危险性" tabindex="-1">就业的心理学与危险性 <a class="header-anchor" href="#就业的心理学与危险性" aria-label="Permalink to &quot;就业的心理学与危险性&quot;">​</a></h3><p><img src="'+r+'" alt=""></p><p>我把朝九晚五的工作视为一块垫脚石。</p><p>我对它们的不满在于，它们滋生自满情绪，并且对你的心理健康很危险。</p><p>挑战正是让生活充满乐趣和趣味的原因。</p><p>如果你因为从不追求更多而停止了个人进化，你就会失去目标感和满足感。</p><p>创业是长期主义者唯一符合逻辑的选择。</p><p>创业是一条充满不确定性的道路。</p><p>就像在丛林中披荆斩棘。</p><p>你需要学习学校里不教的技能。</p><p>你需要坦然面对失败、拒绝和缓慢的进展。</p><p>你需要从错误中学习，明天继续出场，并不断推进，直到你挖到金子。</p><p>你的心智天生就是为了狩猎而设计的。</p><p>物理世界改变的速度远比我们大脑适应的速度要快得多。</p><p>我们仍然拥有与祖先相同的神经生物学过程。</p><p>如果你在朝九晚五的工作里待得太久，你就会变成隔间里的猴子。</p><p>当你困在朝九晚五的工作中（或者像代运营公司或自由职业这样的新式朝九晚五），你就生活在永恒的“已知”中。你无法在“已知”中做出新发现。</p><p>你变得无聊、抑郁，觉得生活毫无意义，因为你获取多巴胺的唯一途径只剩下表面肤浅的来源。</p><p>你从不冒险，从不探索未知，也从不去发现那些能提升大脑多巴胺水平的新知识、新工具和新潜力。</p><p>作为一个创业者，你为了生存而“狩猎”，通过收集知识、创造有价值的产品，并将其展示在能从中受益的人面前。</p><p>你不需要去猎取食物，但你必须去猎取获取食物的资源，比如用来投资更好未来的金钱。</p><p>亚里士多德谴责体力劳动，认为它对身体和灵魂有害。</p><p>古希腊人将工作视为生活中必要的一部分。但工作仅仅是通向休闲、创造力和沉思的手段，因为他们认为这些才是幸福的关键。</p><p>没有工作，休闲就失去了意义，反之亦然。</p><p>生活开始缺乏平衡与对比。</p><p>体力劳动并不总是坏事。但为了生存或地位而完成无脑的任务，让你变得和机器人或动物没什么两样。</p><h2 id="工作的未来是玩耍" tabindex="-1">工作的未来是玩耍 <a class="header-anchor" href="#工作的未来是玩耍" aria-label="Permalink to &quot;工作的未来是玩耍&quot;">​</a></h2><blockquote><p>这个星球上大约有70亿人。我希望有一天，会有将近70亿家公司。——纳瓦尔 (Naval)</p></blockquote><p><em><strong>金钱是一种工具，用来构建你想要但尚未存在的事物。</strong></em></p><p>它不是用来为了获取汽车和房子等物质享受（尽管这些确实可以通过商业、投资或自我提升这样极具精神性的载体来实现）。</p><p>科技和互联网是你构建解决方案的途径，这些方案能够推动个人和集体的进步。</p><p>进化就是用科技解决问题。</p><p>这就是我们人类在做的事。这是我们的优势。正是这一点将你与其他生物区分开来，并造就了我们生活的这个充满摩天大楼、图书馆、体育运动和无限互联网的复杂世界。</p><p>我们凭借计划、专注和创造力来构建、创造并解决我们自己的问题。</p><p>人类有一种与生俱来的驱动力，要在基因<em>和</em>意识中留存信息。</p><p>自人类黎明以来，我们就一直为了延长寿命和保持青春而发展科技。</p><p>想要保全我们肉体的驱动力是天生的，但其原因并不像大多数人想的那样。</p><p>人类是在概念层面上生存的。</p><p>我们试图复制我们思想的内容。</p><p>那些造就了我们之所以为我们的想法、信念和价值观。</p><p>孩子仅仅是一个肉体吗？当他们出生时，他们有“自我”吗？你仅仅是通过在生理上生下他们来创造一个孩子吗？还是你在将你的精神种子喷洒到他们的大脑中，以塑造他们的身份？</p><p>为了让我们变得不朽，我们努力保全物理形态和延长青春的驱动力是必要的，这能增加我们传播思想的时间，让我们的思想在意识中泛起涟漪，并（希望能）在善恶之战中获胜。生物圈（生物学）必须保持完好无损，心智圈（精神）才能不断扩张并超越到下一个未知的阶段。</p><p>从这个意义上说，这就解释了我们为什么会做我们所做的事。</p><p>作者写书是为了变得不朽，并把他们的思想传承下去，从而在世界各地创造出无数个“自我”。</p><p>作者和创作者拥有的孩子比成吉思汗还要多。</p><p>我们阅读书籍，并吸收那些与我们的目标相一致的想法，将其作为我们身份认同的一部分。</p><p>而由于大多数人的目标都是社会强加给他们的，所以他们在感知和存储那些强化他们身份认同的信息。大众就是社会的孩子。</p><p><strong>这一切都指向了工作的未来。</strong></p><p>通过进化和技术，我们一直在将体力劳动从我们的视线中移除。</p><p>在我看来，这似乎就是人类想要进一步追求创造性工作、以推动心智和意识扩张与统一的驱动力。</p><p>我们想要在自己想要的时间，做自己想做的事情。通过追求我们的兴趣，解决我们的问题，以及构建能在人间创造天堂的解决方案，朝着积极的方向前进。</p><p>对于绝大多数人来说，这从未像今天这般成为一个现实的选择。</p><p>我们手头拥有相应的科技，可以借助互联网来创造我们的理想生活。</p><h3 id="数字文艺复兴" tabindex="-1">数字文艺复兴 <a class="header-anchor" href="#数字文艺复兴" aria-label="Permalink to &quot;数字文艺复兴&quot;">​</a></h3><p>在我眼中，工作的未来属于富有创造力的人。</p><p>那些作家。</p><p>那些设计师。</p><p>那些演说家。</p><p>那些建设者。</p><p>那些创作者。</p><p>那些知识合成者。</p><p>收入最高的个人现在是，将来也会是那些利用大脑的创造能力去解决那些阻碍人类进步的问题的人。</p><p>这就是我在<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">《两小时作家》(2 Hour Writer)</a>中教授的内容。</p><p>想法是构筑更美好未来的基石。</p><p>想法是创意工作者的主要追求。</p><p>人们没有意识到的是，实现看似不可能的想法是有方法可循的。你只需要创造出一条能够让你将那种现实转化为实际的路径。</p><p>埃隆·马斯克 (Elon Musk) 想要登陆火星。</p><p>几年前，这是不可能的，但它现在正一天比一天变得可能。</p><p>他并不是一开始就创立了 SpaceX。</p><p>他做出了明智的选择（在许多愚蠢的选择之中，你无法跳过犯错的环节），以至于现在拥有了公司、资本，以及一条登陆火星的路径。</p><p>大多数人试图让不可能变为可能，但却失败了，因为他们跳过了构建那些必须先行的想法的步骤。</p><p>犁出现在拖拉机之前。</p><p>档案柜出现在第二大脑之前。</p><p>马车出现在汽车之前。</p><p>而大多数时候，人们并不知道如果他们没有去构建其他那些使其成为可能的解决方案，汽车根本就不会存在。</p><p>从实际意义上讲，你根本不知道你的未来有什么可能。如果你不去为生活中的个人问题构建解决方案，你就永远不会发现。</p><p>我们正在经历一场似乎是第二次文艺复兴的浪潮。一场数字化的文艺复兴。一场永恒的文艺复兴。</p><p>随着我们向新星球扩张，人类数量达到数万亿，将会涌现出成千上万个爱因斯坦和尼采。</p><p>我们回到了一个艺术家、思想家和创作者的冒险能得到回报的时代。</p><p>这不是一个属于专才的时代。</p><p>也不属于通才。</p><p>我们生活在一个<a href="/letters/become-a-digital-renaissance-man-and-join-the-new-rich">“专精通才” (specialized generalism)</a>的时代。</p><p>你必须像激光一样聚焦于一个特定的未来愿景，并掌握通用的技能和知识，从而实现每一个递进的目标，正是这些目标<em>创造</em>了那个愿景。</p><p>成功并不是学习一项技能那么简单。</p><p>正如我们将发现的那样，终身的自我教育和技能获取——且与自发的目标相一致——是你通往个人主权的关键。</p><h3 id="新经济" tabindex="-1">新经济 <a class="header-anchor" href="#新经济" aria-label="Permalink to &quot;新经济&quot;">​</a></h3><p>宇宙分离又重聚，就像海水蒸发然后凝结成雨降落回大地。</p><p>我们将其称为中心化与去中心化的循环。</p><p>社交媒体导致了从中心化媒体向去中心化媒体的转变。</p><p>知识合成者——或者说创作者——就是去中心化的媒体公司。</p><p>他们构成了任何只要有网络连接的人都能访问的新公共教育系统。</p><p>个人正在创造新工作，教授新信息，并开创学校和政府无法跟上的新路径。</p><p>很少有人认识到社交媒体作为新数字社会的重要性。</p><p>大多数人只把它看作一个娱乐消遣的地方，或者用来在工作中完成几项任务的工具。</p><p>事实上，媒体塑造着文化、社会和经济。</p><p>媒体是我们学习的途径。</p><p>媒体是我们获取新信息的途径。</p><p>媒体是我们传达自己业务价值的途径。</p><p>媒体占据了我们生活的一大部分。它创造了一种社会结构，人们依靠这种结构才能让文明按照现有的方式运转。</p><p>社交媒体是集体的意识，它传播思想，供人们采纳并作为自身身份认同的一部分。</p><p>身份影响视角。视角影响认知。认知影响我们认为生活中什么是重要的或有价值的。</p><p>社交媒体，无论你是否在使用，都在个人层面上改变着我们的行为，并通过交流在整个社会中荡起涟漪。社交媒体正在用它所承载和传播的理念创造出新的自我。</p><p>一个创作者可以在眨眼之间向数百万人发送一条信息。想象一下，如果在50年前试图向一百万人发送信息。那将需要几个月甚至更长的时间。</p><p>社交媒体改变了我们花钱的方式，因为它改变了创作者采纳和传播的信息。</p><p>有这样一些综合者，他们追求自己的目标，收集理念以创造性地实现目标，并向读者传播有价值的信息。</p><p>还有那些普通的网红，他们为了强化自我，用外表而不是深度来吸引大众。他们可能正在无意识地将社会引向死胡同。</p><p>世界需要更多的综合者。</p><p>价值创造者探索现实中未知的缝隙，并传播那些他人可以利用现有技术进行构建的理念，从而推动集体的进步。</p><p>如果你想成为一名综合者，这就是我创办 Kortex 大学的初衷，<a href="https://university.kortex.co/" target="_blank" rel="noreferrer">你可以在这里申请入学</a>。</p><p>随着自动化和人工智能呈指数级增长，人们转向人类来满足对媒体内容的渴求，这就顺理成章了。</p><p>个人品牌。创作者。综合者。本质上是同一回事，只是在细微差别和影响力上有所不同。</p><p>他们根据自己的兴趣进行教育、娱乐和启发他人。</p><p>除非我们重写集体心理（这种心理在几百年来并没有太大变化），否则这是不可避免的。人是被人类吸引的，而不是机器人。</p><p>不过，机器人在减少劳动力和增加人类创造力方面确实有其用武之地。</p><p><strong>现代商业是自我的延伸。</strong></p><p>它是承载你目标的容器。</p><p>你的目标会不断进化，你必须解决生活中的表面问题，才能触达你最深层的目标。</p><p>这里的规律就是永恒的市场（资金流动最密集的地方）。</p><p>健康、财富和人际关系。</p><p>通过互联网获取所需的技能和知识来<a href="/letters/the-self-reliant-career-path-how-to-generate-independent-income">解决你自己的问题</a>。</p><p>将你学到的东西以免费内容和付费产品的形式传递下去。</p><p>这样做，你不仅创造了一个独立的收入来源，还创造了巨大的社会杠杆。</p><p>新经济由创作者组成，他们销售能够推动其社群进步的产品。</p><p>有人卖信息。有人卖棉质衣服，因为他们看到聚酯纤维作为内分泌干扰物的危险。有人卖护肤品。</p><p>科技降低了产品创造的门槛，因此我们可以靠做自己喜欢的事情谋生，同时不可估量地提升自己（以及我们社群或读者群中的人）。</p><h2 id="如何开创你自己的事业" tabindex="-1">如何开创你自己的事业 <a class="header-anchor" href="#如何开创你自己的事业" aria-label="Permalink to &quot;如何开创你自己的事业&quot;">​</a></h2><p><img src="'+t+'" alt=""></p><p>好奇心导向学习。</p><p>学习导向痴迷。</p><p>痴迷导向一种你从未想过可能实现的截然不同的生活。</p><p>一种充满乐趣、充满胜利的生活，并对那些能在你从现实中开辟出的道路中看到价值的人产生影响。</p><p>有了可供使用的——快速发展的——技术，我们不再需要继续做社会的傀儡。</p><p>我们可以做出有意识的个人选择，利用那些在新经济中为我们打造的工具。</p><p>我们有机会去创造一份事业，而不是被指派一份工作。</p><p>这是未来的职业道路，你在其中选择什么方向取决于你自己：</p><h3 id="自我教育" tabindex="-1">自我教育 <a class="header-anchor" href="#自我教育" aria-label="Permalink to &quot;自我教育&quot;">​</a></h3><p>综合者就是数字时代的文艺复兴式人物。</p><p>他们是不断自我教育的人。</p><p>他们获取知识和技能以实现他们的目标。</p><p>他们让自己创造的目标，而不是社会分派给他们的目标，成为他们兴趣的指南针。</p><p>未来的工作基于创造力，而非生产力。</p><p>创造力是利用你从学习技能和兴趣中获取的多元知识来实现一个目标。</p><p>如果你没有学过任何被要求学习之外的东西，那你可能还没有为自己的目标进行过投资，你还有很长的路要走。</p><p>正如在<a href="/letters/you-wont-be-the-same-person-in-6-months-master-anything-fast">上周的信</a>中讨论的那样，目标塑造了你生活的方方面面、你的身份以及你获取的知识。</p><p>这不是为了成为某些技能和兴趣领域的专家。</p><p>这更多是为了有源源不断的信息输入，为你构建的事物提供燃料，以实现你的目标。</p><p>如果你还没有开始，你必须从基础开始。</p><p>头脑、身体、精神和商业。</p><p>自我教育，学习如何解决你自己和他人生活中最迫切、最有利可图的问题。</p><p>如果你想相当快地赚钱，你必须解决你自己的表面问题，并帮助他人解决他们的问题。</p><p>尽你的一份力量提升集体意识，帮助他人超越那些将他们困在较低意识状态的问题。</p><p>围绕健身、人际关系、心理健康和财务自由去学习、构建并销售一款产品。</p><p>通过追求这些目标，你的道路将是独一无二的。很明显，没有人的道路是完全相同的。你通过实现这些目标获取的知识对你来说也是独一无二的。</p><p>每一个人的细分领域都是自我实现。</p><p>在这场技术革命之前，人们并不会在公开场合进行自我实现。</p><p>那些造火箭的人也处于自我实现的细分领域中。他们正在推进人类的潜能。</p><p>但是，你有能力提升自己，从中获利，然后追求任何你想要的东西。</p><h3 id="代码与内容" tabindex="-1">代码与内容 <a class="header-anchor" href="#代码与内容" aria-label="Permalink to &quot;代码与内容&quot;">​</a></h3><p>要想在未来的工作中占据优势，你必须掌握某些技能。</p><p><strong>元技能</strong></p><p>代码和内容创造了互联网。</p><p>它们涵盖了你需要学习的每一项其他技能。</p><p>而且，如果所有能在互联网上完成的事情都将在互联网上完成，那么学习这些就不再是可选项。</p><p><strong>结果导向技能</strong></p><p>你不需要学习编写代码，但你需要具备技术诀窍。</p><p>你需要了解可以用哪些工具来打造更美好的生活。</p><p>邮件营销、平面设计、视频剪辑、网站和漏斗构建</p><p>这些都是帮助你在数字社会中作为个人品牌站稳脚跟的技术工具。</p><p>这种意义上的“代码”，指的是数字资产。</p><p>尽你所能去学习，以构建更多的数字资产，让人们能够找到并关注。</p><p><strong><a href="/letters/the-1-million-dollar-skill-stack-learn-in-this-order">长青技能</a></strong></p><p>代码是内容的容器，而内容是让你出现在他人面前、吸引他们购买你产品的唯一途径。</p><p>写作、演讲、营销和销售这些技能，能够<em>为</em>你的结果导向技能提供具有影响力的信息传达。</p><p>你不能只是随便写篇社交媒体帖子，就指望它表现出色。</p><p>你需要了解其中的机制和心理学。</p><p>营销和销售就是应用机制和心理学。</p><p><strong>个人兴趣</strong></p><p>现在，你正在学习大量在这个时代利用社交媒体建立一家企业（你的数字简历）所需的技能。</p><p>你已经学会了如何通过你的邮件、内容和网页来进行写作、演讲、营销和销售。</p><p>那些技能——加上真正发布内容——就是你开始积累受众的方式。</p><p>但你的个人兴趣才是让你脱颖而出的东西，<em>并且决定了你卖什么。</em></p><p>上述任何与商业相关的都可以被算作个人兴趣，但你研究头脑、身体或精神所学到的任何东西也一样可以。</p><p>你的任务是利用你的技能，将那些让你与众不同的兴趣变现。</p><h3 id="员工与创业者" tabindex="-1">员工与创业者 <a class="header-anchor" href="#员工与创业者" aria-label="Permalink to &quot;员工与创业者&quot;">​</a></h3><p>大多数人梦想成为一家价值十亿美元公司的 CEO，却甚至当不了自己生活的 CEO。</p><p>员工思维很难打破：</p><ul><li>除了你已经知道的，你不再去追求任何新事物</li><li>除了指派给你的工作，你不会继续去拓展你的技能树</li><li>你在工作和生活中等待被告知要做什么，你不会自己做决定</li></ul><p>即使你搬出去了，你的父母仍然是你的老板。这种潜移默化的程序设定依然在牵扯着你的大脑。</p><p>创业者拥有一套符合我们祖先和自然规律的独特特质：</p><ul><li>他们闯入未知领域并开辟新路径</li><li>他们为创造性问题构建解决方案以推动人类进步</li><li>他们从不停止获取知识并将其应用到现实中</li></ul><p>在新经济中，你可以选择任何一条路。</p><p>雇主根据你的社交媒体进行招聘。</p><p>创作者根据你的社交媒体进行招聘。</p><p>品牌根据你的社交媒体进行招聘。</p><p>客户根据你的社交媒体进行雇佣。</p><p>消费者根据你的社交媒体进行购买。</p><p>你可以当一名员工，但要明白，如果你想要完全掌控你的生活和收入，创业是你终将要迈出的一步。</p><h3 id="被指派的产品与创造出的产品" tabindex="-1">被指派的产品与创造出的产品 <a class="header-anchor" href="#被指派的产品与创造出的产品" aria-label="Permalink to &quot;被指派的产品与创造出的产品&quot;">​</a></h3><p>“现在每个人都有个产品要卖。”</p><p>我在 Chris Williamson 推广他新款效率饮料的帖子下看到了这句话。</p><p>评论者是以一种消极的语气说出来的。</p><p>就好像他们不是在为某个有产品的人工作一样。</p><p>是的，现在每个人都有产品。因为如果你不想被指派去卖别人的产品，这就是必须的。</p><p>“我不想做销售，感觉很下作。”</p><p>那你根本不懂销售。你现在就在向我推销你的观点，以此来复制并维系你那狭隘的身份认同。</p><p><em>什么都不做，你就在允许那些觉知和智力都不如你的人获得比你更多的注意力、影响力和金钱。</em></p><p><em>什么都不做，你就成了社会的傀儡，被指派去过一种无意识的生活：推销别人的产品，却对此毫无察觉。</em></p><p>创造一款你自己会购买、使用并从中受益的产品。</p><p>那是商业中唯一的捷径。</p><p>你属于某个细分领域，你购买过那个细分领域的产品，如果你对商业有一点了解，你就会跳过50%的试错，去卖你买过的东西，只是做得更好。</p><h3 id="分发渠道与杠杆" tabindex="-1">分发渠道与杠杆 <a class="header-anchor" href="#分发渠道与杠杆" aria-label="Permalink to &quot;分发渠道与杠杆&quot;">​</a></h3><blockquote><p>建立分发渠道，然后再去构建任何你想要的东西。——Jack Butcher</p></blockquote><p>如何创办一家价值十亿美元的公司：</p><p>别去创办。</p><p>从一个人开始。</p><p>利用可供你使用的技术作杠杆。</p><p>布局数字地产，直到你的产品和服务拥有充足的分发渠道。</p><p>每天写帖子，让它们留在你的主页上。</p><p>与他人建立人脉关系，让他们分享你的内容（<a href="/letters/how-to-actually-grow-on-social-media-what-they-dont-tell-you">这样你就能脱离算法的控制实现增长</a>）。</p><p>上播客来建立你的权威。</p><p>推广你的时事通讯，从而真正拥有你的受众。</p><p>赠送免费的小产品，以进一步扩大你的时事通讯订阅量。</p><p>卖一款低客单价的产品，让更多人对你的品牌产生忠诚。</p><p>拥有1万名受众、1千名时事通讯订阅者和100个人脉关系——你想做什么都可以。</p><p>在这个阶段，你已经拥有了赚取全职收入的资源。</p><p>在这之上，你可以把多余的现金注入到建设你的梦想公司或进行投资。</p><p>这封信是为了让你从宏观全局去理解。</p><p>想要获取实际的操作步骤，请点击这封信中的任意链接，查看过往的信件或能提供帮助的产品。</p><p>感谢你的阅读。</p><p>Dan</p><p>P.S. Kortex University 的学员可以抢先体验我们的软件。此外，在创造属于你自己的新经济职业生涯方面，这里的教育体验是无与伦比的。<a href="https://university.kortex.co/" target="_blank" rel="noreferrer">今天就申请加入下一期。</a></p><hr><p><a href="/en/letters/the-future-of-work-is-play-how-to-create-your-own-career">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',254))])}const x=o(u,[["render",d]]);export{y as __pageData,x as default};
